param([switch]$Aplicar)
$ErrorActionPreference = 'Stop'
$dest = Join-Path (Get-Location) 'src/modulos/auditoria/AuditoriaView.vue'
if (-not (Test-Path $dest)) { throw 'Ejecuta desde la raiz del proyecto LERABOT: no se encuentra AuditoriaView.vue' }
Write-Host 'LERABOT Fase 5 - Mejora visual de Auditoria' -ForegroundColor Cyan
Write-Host 'Archivo: src/modulos/auditoria/AuditoriaView.vue'
Write-Host 'Incluye KPIs, dona, barras, filtros select, fechas, modal JSON y tabla.'
Write-Host 'NO ejecuta AWS, GET/PUT, despliegues ni cambios backend.'
if (-not $Aplicar) { Write-Host 'VISTA PREVIA: agrega -Aplicar'; exit 0 }
$backup = "$dest.bak-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
Copy-Item $dest $backup -ErrorAction Stop
